        // GPU: D3D11 compute dispatch Hz from GpuStressService
        private static readonly (double hz, string gpu)[] _gpuRefs =
        {
            (20,   "Intel HD 4000"),  (50,   "GeForce GT 755M"),
            (150,  "GTX 1050"),       (250,  "GTX 1650"),
            (400,  "GTX 1660 Super"), (550,  "Radeon RX 6600"),
            (900,  "RTX 3070"),       (1500, "RTX 4070"),
            (2500, "RTX 4090"),
        };

        internal static string NearestCpuRef(int score)
        {
            var best = _cpuRefs[0];
            foreach (var r in _cpuRefs)
                if (Math.Abs(r.score - score) < Math.Abs(best.score - score)) best = r;
            return best.cpu;
        }
        internal static string NearestGpuRef(double hz)
        {
            var best = _gpuRefs[0];
            foreach (var r in _gpuRefs)
                if (Math.Abs(r.hz - hz) < Math.Abs(best.hz - hz)) best = r;
            return best.gpu;
        }

        private bool IsLightThemeActive() =>
            SMDWin.Services.ThemeManager.IsLight(SMDWin.Services.SettingsService.Current.ThemeName) ||
            (SMDWin.Services.SettingsService.Current.ThemeName == "Auto" &&
             !SMDWin.Services.ThemeManager.IsDark(SMDWin.Services.ThemeManager.ResolveAuto()));

        internal void OpenCpuBenchWindow_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var win = new BenchmarkWindow(BenchmarkWindow.Kind.Cpu, IsLightThemeActive())
                {
                    Owner = this,
                    GetCurrentCpuLoad = () => _cachedCpuPct >= 0 ? _cachedCpuPct : 0f,
                };
                SetNavTaskBadge("TaskBadgeStress", true);
                win.ShowDialog();
                SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.OpenCpuBenchWindow"); }
        }

