        internal async void RunBench_Click(object sender, RoutedEventArgs e)
        {
            if (BtnRunBench != null) BtnRunBench.IsEnabled = false;

            // Show inline bench card
            if (InlineBenchCard != null) InlineBenchCard.Visibility = Visibility.Visible;
            if (BenchScoreBadge != null)  BenchScoreBadge.Visibility  = Visibility.Collapsed;

            void SetProgress(double pct, string msg) => Dispatcher.InvokeAsync(() =>
            {
                if (TxtBenchStatus != null) TxtBenchStatus.Text = msg;
                if (BenchProgressFg != null && BenchProgressBg != null)
                    BenchProgressFg.Width = Math.Max(0,
                        (BenchProgressBg.ActualWidth > 0 ? BenchProgressBg.ActualWidth : 400) * Math.Clamp(pct, 0, 1));
            });

            try
            {
                var cts = new System.Threading.CancellationTokenSource(TimeSpan.FromSeconds(120));

                await Task.Run(async () =>
                {
                    double cpuScore = 0, ramScore = 0, ssdScore = 0;

                    // ── 1. CPU ──────────────────────────────────────────────
                    SetProgress(0.05, "CPU benchmark — SHA-256 + Mandelbrot + FFT (9s)…");
                    try
                    {
                        var r = SMDWin.Services.CpuStressor.RunFullBenchmark(3.0);

                        // Use CompositeScore (0-1000, where i5-8400 = 500) → map to /30 pts
                        // i5-4570 ~350 → 10.5; i7-12700K ~900 → 27; cap at 30
                        cpuScore = Math.Min(30, r.CompositeScore / 33.33);

                        string shaFmt  = r.Sha256HashesPerSec >= 1_000_000
                            ? $"{r.Sha256HashesPerSec/1_000_000:F2}M SHA/s"
                            : $"{r.Sha256HashesPerSec/1_000:F0}K SHA/s";
                        string cpuDisp = $"Score {r.CompositeScore}  ·  similar to {NearestCpuRef(r.CompositeScore)}  ·  {shaFmt}";

                        await Dispatcher.InvokeAsync(() =>
                        {
                            if (TxtBenchCpuVal != null)   TxtBenchCpuVal.Text   = cpuDisp;
                            if (TxtBenchCpuScore != null) TxtBenchCpuScore.Text = $"{cpuScore:F0}/30";
                        });
                    }
                    catch (Exception ex)
                    {
                        await Dispatcher.InvokeAsync(() => { if (TxtBenchCpuVal != null) TxtBenchCpuVal.Text = $"Error: {ex.Message}"; });
                    }

                    // ── 2. RAM ──────────────────────────────────────────────
                    SetProgress(0.40, "RAM benchmark — latency + bandwidth (5s)…");
                    try
                    {
                        double latNs = await SMDWin.Services.RamLatencyBenchmark.RunAsync(cts.Token);
                        // DDR5-6000 ~30ns → 25 pts; DDR4-3200 ~55ns → 18 pts; DDR3-1600 ~80ns → 11 pts
                        ramScore = latNs > 0 ? Math.Min(25, Math.Max(0, 35.0 - latNs * 0.25)) : 0;
                        await Dispatcher.InvokeAsync(() =>
                        {
                            if (TxtBenchRamVal != null)   TxtBenchRamVal.Text   = latNs > 0 ? $"Latency {latNs:F1} ns" : "—";
                            if (TxtBenchRamScore != null) TxtBenchRamScore.Text = $"{ramScore:F0}/25";
                        });
                    }
                    catch (Exception ex)
                    {
                        await Dispatcher.InvokeAsync(() => { if (TxtBenchRamVal != null) TxtBenchRamVal.Text = $"Error: {ex.Message}"; });
                    }

                    // ── 3. SSD ──────────────────────────────────────────────
                    SetProgress(0.65, "SSD benchmark — sequential read (20s)…");
                    try
                    {
                        var ssdSvc = new SMDWin.Services.DiskBenchmarkService();
                        using var ssdCts = System.Threading.CancellationTokenSource.CreateLinkedTokenSource(cts.Token);
                        ssdCts.CancelAfter(TimeSpan.FromSeconds(25));
                        var ssdRes = await ssdSvc.RunAsync(@"C:\", ssdCts.Token, null);
                        double readMBps = ssdRes.SeqReadMBs;
                        // Piecewise scale — matches real-world tiers:
                        // HDD ~120 MB/s → 6 · SATA SSD ~550 MB/s → 17 · NVMe ~7000 MB/s → 25
                        ssdScore = readMBps switch
                        {
                            <= 0    => 0,
                            <= 150  => readMBps / 150.0 * 8.0,
                            <= 600  => 8.0  + (readMBps - 150) / 450.0  * 10.0,
                            <= 7000 => 18.0 + (readMBps - 600) / 6400.0 * 7.0,
                            _       => 25.0,
                        };
                        await Dispatcher.InvokeAsync(() =>
                        {
                            if (TxtBenchSsdVal != null)   TxtBenchSsdVal.Text   = readMBps > 0 ? $"Read {readMBps:F0} MB/s  ·  Write {ssdRes.SeqWriteMBs:F0} MB/s" : "—";
                            if (TxtBenchSsdScore != null) TxtBenchSsdScore.Text = $"{ssdScore:F0}/25";
                        });
                    }
                    catch (OperationCanceledException)
                    {
                        await Dispatcher.InvokeAsync(() => { if (TxtBenchSsdVal != null) TxtBenchSsdVal.Text = LanguageService.S("Common", "TimedOut"); });
                    }
                    catch (Exception ex)
                    {
                        await Dispatcher.InvokeAsync(() => { if (TxtBenchSsdVal != null) TxtBenchSsdVal.Text = $"Error: {ex.Message}"; });
                    }

                    // ── Scor total (CPU 30, RAM 25, SSD 25 = 80; GPU reserved 20) ──
                    SetProgress(1.0, "Complete.");
                    double total = cpuScore + ramScore + ssdScore;

                    // Grade based on /80 (GPU column reserved)
                    double pct80 = total / 80.0;
                    string grade = pct80 >= 0.90 ? "S  Exceptional"
                                 : pct80 >= 0.75 ? "A  Excellent"
                                 : pct80 >= 0.60 ? "B  Good"
                                 : pct80 >= 0.45 ? "C  Average"
                                 : pct80 >= 0.30 ? "D  Below average"
                                 : "F  Slow";

                    await Dispatcher.InvokeAsync(() =>
                    {
                        if (TxtBenchTotalScore != null) TxtBenchTotalScore.Text = $"{total:F0}";
                        if (TxtBenchGrade != null)      TxtBenchGrade.Text      = $"— {grade}";
                        if (BenchScoreBadge != null)    BenchScoreBadge.Visibility = Visibility.Visible;
                        if (TxtBenchStatus != null)
                            TxtBenchStatus.Text = LanguageService.S("Disk", "BenchmarkComplete")
                                + (_lastThrottle?.BoostDisabled == true
                                    ? " · " + LanguageService.S("Throttle", "TurboOffBench", "Turbo is turned off in the power plan — the score is below what this processor can do.")
                                    : "");
                        // Color total score by performance
                        if (TxtBenchTotalScore != null)
                            TxtBenchTotalScore.Foreground = pct80 >= 0.75 ? _brGreen
                                                          : pct80 >= 0.45 ? _brOrange
                                                          : _brRed;
                    });

                }, cts.Token).ContinueWith(_ => Dispatcher.InvokeAsync(() =>
                {
                    if (BtnRunBench != null) BtnRunBench.IsEnabled = true;
                }));
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "RunBench_Click");
                ShowToastError(string.Format(LanguageService.S("Msg", "BenchmarkErrorFmt"), ex.Message));
                if (BtnRunBench != null) BtnRunBench.IsEnabled = true;
            }
        }

