        // ── Stress Test PDF Export ────────────────────────────────────────────
        internal async void ExportStressPdf_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                var dlg = new Microsoft.Win32.SaveFileDialog
                {
                    Title            = MainWindow.PT("Export Stress Report"),
                    Filter           = "PDF Document|*.pdf",
                    FileName         = $"SMDWin_Stress_{DateTime.Now:yyyyMMdd_HHmm}.pdf",
                    InitialDirectory = SMDWin.Services.SettingsService.GetEffectiveReportFolder(),
                };
                if (dlg.ShowDialog() != true) return;

                string path = dlg.FileName;
                if (BtnExportStressPdf != null) BtnExportStressPdf.IsEnabled = false;

                await Task.Run(() => GenerateStressPdf(path));

                ShowToast(string.Format(LanguageService.S("Msg", "StressReportSavedFmt"), System.IO.Path.GetFileName(path)), "", 3500);
                System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path) { UseShellExecute = true });
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "ExportStressPdf_Click");
                ShowToastError(string.Format(LanguageService.S("Msg", "ExportFailedFmt"), ex.Message));
            }
            finally
            {
                if (BtnExportStressPdf != null) BtnExportStressPdf.IsEnabled = true;
            }
        }

        // ── GPU Benchmark ─────────────────────────────────────────────────────
        private bool _gpuBenchRunning = false;

        private async void RunGpuBench_Click(object sender, RoutedEventArgs e)
        {
            if (_gpuBenchRunning) return;
            _gpuBenchRunning = true;

            if (BtnGpuBench != null) BtnGpuBench.IsEnabled = false;
            if (TxtBtnGpuBench != null) TxtBtnGpuBench.Text = LanguageService.S("Stress", "GpuBenchRunning");

            // Show inline bench card with GPU status
            if (InlineBenchCard != null) InlineBenchCard.Visibility = Visibility.Visible;
            if (TxtBenchStatus != null) TxtBenchStatus.Text = LanguageService.S("Stress", "GpuBenchStatus");
            if (BenchScoreBadge != null) BenchScoreBadge.Visibility = Visibility.Collapsed;

            try
            {
                var cts = new System.Threading.CancellationTokenSource(TimeSpan.FromSeconds(30));

                await Task.Run(async () =>
                {
                    double gpuScore = 0;
                    string gpuDisp  = "—";

                    try
                    {
                        // Start GPU stress and let it warm up for 3s (longer than before = more stable)
                        _gpuStress.Start();
                        Dispatcher.Invoke(() => SetNavTaskBadge("TaskBadgeStress", true));
                        await Task.Delay(3000, cts.Token);   // warmup: shader compile + loop settle
                        await Task.Delay(8000, cts.Token);   // measure window
                        double hz  = _gpuStress.DispatchHz;
                        _gpuStress.Stop();
                        Dispatcher.Invoke(() => SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning));

                        if (hz > 0)
                        {
                            // Scale: GT 755M ~50 Hz → 5 pts; RX 6600 ~500 Hz → 18 pts; RTX 4090 ~2000+ Hz → 25
                            gpuScore  = Math.Min(25, Math.Max(0, 2.0 + hz / 100.0));
                            bool warp = _gpuStress.StatusText.Contains("WARP", StringComparison.OrdinalIgnoreCase);
                            gpuDisp   = warp
                                ? $"{hz:F0} dispatch/s (software — no hardware GPU)"
                                : $"{hz:F0} dispatch/s  ·  similar to {NearestGpuRef(hz)}";
                        }
                        else
                        {
                            gpuDisp = "Not available (D3D11 init failed)";
                        }
                    }
                    catch (OperationCanceledException) { try { _gpuStress.Stop(); Dispatcher.Invoke(() => SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning)); } catch (Exception ex) { AppLogger.Debug(ex.Message); } }
                    catch (Exception ex)
                    {
                        try { _gpuStress.Stop(); Dispatcher.Invoke(() => SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning)); } catch (Exception stopEx) { AppLogger.Debug(stopEx.Message); }
                        gpuDisp = $"Error: {ex.Message}";
                    }

                    double finalScore = gpuScore;
                    string finalDisp  = gpuDisp;

                    await Dispatcher.InvokeAsync(() =>
                    {
                        if (TxtBenchStatus != null)
                            TxtBenchStatus.Text = $"GPU: {finalDisp}  ·  {finalScore:F0}/25 pts";
                        if (TxtBenchTotalScore != null)
                        {
                            // Try to add to existing total
                            if (double.TryParse(TxtBenchTotalScore.Text, out double prev))
                                TxtBenchTotalScore.Text = $"{prev + finalScore:F0}";
                        }
                    });

                }, cts.Token);
            }
            catch (Exception ex) { AppLogger.Debug($"RunGpuBench_Click: {ex.Message}"); }
            finally
            {
                _gpuBenchRunning = false;
                if (BtnGpuBench != null) BtnGpuBench.IsEnabled = true;
                if (TxtBtnGpuBench != null) TxtBtnGpuBench.Text = LanguageService.S("Stress", "BtnGpuBenchLabel");
            }
        }

